struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    fn area(&self) -> u32 {
        self.width * self.height
    }

    fn is_square(&self) -> bool {
        self.width == self.height
    }
}

fn main() {
    let r = Rectangle { width: 3, height: 4 };
    println!("area {}, square: {}", r.area(), r.is_square());
}

struct Account {
    balance: i64,
}

impl Account {
    fn new() -> Account {
        Account { balance: 0 }
    }

    fn deposit(&mut self, amount: i64) {
        self.balance += amount;
    }
}

fn main() {
    let mut acc = Account::new();
    acc.deposit(50);
    acc.deposit(25);
    println!("balance {}", acc.balance);
}

